package com.fixmer.mared;
import com.fixmer.genesis.technology.server.remote.*;import com.fixmer.genesis.technology.server.firstlaunch.*;
import java.nio.file.*;import java.util.*;import java.security.*;
/** Actual generation/session/HMAC/queue tests; no Minecraft ServerPlayer or native Job is simulated as proof. */
public final class DedicatedChecks75 {
 static int checks;interface Work{void run()throws Exception;}static void check(boolean v){if(!v)throw new AssertionError("check "+checks);checks++;}static void refuse(Work w)throws Exception{try{w.run();throw new AssertionError("Unexpected permission");}catch(java.io.IOException|IllegalArgumentException|IllegalStateException expected){checks++;}}
 static void write(Path p,byte[] key,Map<String,String> value)throws Exception{Files.write(p,LocalApply67.sign(key,value));}
 static void tests(Path root)throws Exception{
  byte[] key=new byte[32];new SecureRandom().nextBytes(key);Files.write(root.resolve("owner74.key"),key);UUID run=UUID.randomUUID();var marker=Map.of("schema","75","run",run.toString());var c=Map.of("schema","74","run",run.toString(),"generation","2","inventory","a".repeat(64),"minecraft","1.21.1","neoforge","21.1.264","auth","true","bind","","port","25565");write(root.resolve("server-2.session"),key,c);
  Map<String,String> env=new HashMap<>(Map.of("GENESIS_DEDICATED74_ROOT",root.toString(),"GENESIS_DEDICATED74_RUN",run.toString(),"GENESIS_DEDICATED74_GENERATION","2"));refuse(()->DedicatedSession74.open(env));env.put("GENESIS_DEDICATED75_VERSION","75");refuse(()->DedicatedSession74.open(env));write(root.resolve("owner75"),key,marker);var session=DedicatedSession74.open(env);check(session.repeatable&&session.generation==2);var invalid=new HashMap<>(env);invalid.put("GENESIS_DEDICATED74_GENERATION","33");refuse(()->DedicatedSession74.open(invalid));invalid.put("GENESIS_DEDICATED74_GENERATION","02");refuse(()->DedicatedSession74.open(invalid));
  long now=System.currentTimeMillis();byte[] pub=KeyPairGenerator.getInstance("Ed25519").generateKeyPair().getPublic().getEncoded();var offer=new RemoteOffer69("localhost:25565","https://localhost/genesis/",UUID.randomUUID(),UUID.randomUUID(),null,"1.21.1","21.1.264",1,now,now+3600000,1,"b".repeat(64),FirstLaunchFiles.sha(pub));var proof=new HashMap<>(Map.of("schema","74","run",run.toString(),"generation","2","oldInventory",c.get("inventory"),"newInventory","c".repeat(64),"release",offer.release().toString(),"client",offer.archiveSha(),"server","d".repeat(64),"label","r2","codeSeal","e".repeat(64)));write(root.resolve("prepared74"),key,proof);session.prepared(offer);checks++;proof.put("generation","0");write(root.resolve("prepared74"),key,proof);refuse(()->session.prepared(offer));
  var view=new TreeMap<String,String>();view.putAll(Map.of("schema","75","run",run.toString(),"generation","2","phase","ACTIVE_UPDATED","updated",Long.toString(now),"ready","true","busy","false"));view.putAll(Map.of("control","{}","delta","{}","history","[]","failureCode","","failureStage","","reason",""));write(root.resolve("view75"),key,view);var admin=DedicatedAdmin75.open(root);check(admin.view().equals(view));UUID req=UUID.randomUUID();admin.submit(req,"STAGE","r3");var queued=LocalApply67.verify(key,Files.readAllBytes(root.resolve("request74")));check(queued.get("generation").equals("2")&&queued.get("schema").equals("75")&&queued.get("request").equals(req.toString()));admin.submit(req,"STAGE","r3");checks++;refuse(()->admin.submit(req,"COMMIT","r3"));refuse(()->admin.submit(UUID.randomUUID(),"COMMIT","r3"));write(root.resolve("request74.ack"),key,Map.of("schema","75","run",run.toString(),"request",req.toString()));admin.submit(UUID.randomUUID(),"OFFER","r3");checks++;
  refuse(()->admin.submit(UUID.randomUUID(),"EXEC","r3"));refuse(()->admin.submit(UUID.randomUUID(),"STAGE","../other"));refuse(()->admin.submit(new UUID(0,0),"STAGE","r3"));view.put("updated",Long.toString(now-20000));write(root.resolve("view75"),key,view);refuse(()->admin.submit(UUID.randomUUID(),"STAGE","r3"));view.put("updated",Long.toString(System.currentTimeMillis()));view.put("busy","true");write(root.resolve("view75"),key,view);refuse(()->admin.submit(UUID.randomUUID(),"STAGE","r3"));Files.delete(root.resolve("request74"));admin.submit(UUID.randomUUID(),"SHUTDOWN","r3");checks++;
  view.put("accessToken","must-never-publish");write(root.resolve("view75"),key,view);refuse(admin::view);view.remove("accessToken");view.put("generation","33");write(root.resolve("view75"),key,view);refuse(admin::view);view.put("generation","2");write(root.resolve("view75"),new byte[32],view);refuse(admin::view);
  check(DedicatedAdmin75.mayAdminister(true,true));check(!DedicatedAdmin75.mayAdminister(false,true));check(!DedicatedAdmin75.mayAdminister(true,false));check(!DedicatedAdmin75.mayAdminister(false,false));
  write(root.resolve("owner75"),new byte[32],marker);refuse(()->DedicatedAdmin75.open(root));System.out.println("Dedicated75 actual generation/HMAC/admin-queue checks passed: "+checks+"; permission booleans are explicit inputs, not Minecraft player runtime.");
 }
 public static void main(String[] a)throws Exception{Path root=Files.createTempDirectory("dedicated75-checks-");try{tests(root);}finally{try(var paths=Files.walk(root)){for(Path p:paths.sorted(Comparator.reverseOrder()).toList())Files.delete(p);}}}
}
